  1→import {
  2→  useCallback,
  3→  useEffect,
  4→  useRef,
  5→  useState,
  6→  type ReactNode,
  7→} from 'react';
  8→import { AgentContext } from '../hooks/useAgent';
  9→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
 10→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 11→import { useSessionId } from '../hooks/useSessionId';
 12→import { generateUUID } from '../utils/uuid';
 13→
 14→function generateId() {
 15→  return generateUUID();
 16→}
 17→
 18→export function AgentProvider({
 19→  children,
 20→  refreshTables,
 21→}: {
 22→  children: ReactNode;
 23→  refreshTables: () => Promise<void>;
 24→}) {
 25→  const userSessionId = useSessionId();
 26→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 27→  const [isStreaming, setIsStreaming] = useState(false);
 28→  const abortRef = useRef<AbortController | null>(null);
 29→  const textBufferRef = useRef('');
 30→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 31→  const assistantIdRef = useRef('');
 32→  const segmentsRef = useRef<ContentSegment[]>([]);
 33→  const currentTextRef = useRef('');
 34→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 35→  const sessionIdRef = useRef<string | null>(null);
 36→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 37→  // Keep a ref in sync with messages so sendMessage always reads the latest
 38→  const messagesRef = useRef<ChatMessage[]>(messages);
 39→  useEffect(() => { messagesRef.current = messages; }, [messages]);
 40→  // Cache messages per conversation so switching away doesn't lose in-progress data
 41→  const messagesCacheRef = useRef<Map<string, ChatMessage[]>>(new Map());
 42→  // Track which conversation is currently displayed so background streams can detect they're stale
 43→  const activeConversationIdRef = useRef<string | null>(null);
 44→  // Track which conversation owns the current SSE stream (set in sendMessage).
 45→  // Used as a fallback when React state is stale (e.g. user switches before re-render).
 46→  const streamConversationIdRef = useRef<string | null>(null);
 47→
 48→  const flushText = useCallback(() => {
 49→    const text = textBufferRef.current;
 50→    if (!text) return;
 51→    const id = assistantIdRef.current;
 52→    currentTextRef.current += text;
 53→    setMessages((prev) =>
 54→      prev.map((m) =>
 55→        m.id === id ? { ...m, content: m.content + text } : m
 56→      )
 57→    );
 58→    textBufferRef.current = '';
 59→  }, []);
 60→
 61→  const sendMessage = useCallback(
 62→    async (text: string, conversationId?: string | null) => {
 63→      if (isStreaming) return;
 64→      streamConversationIdRef.current = conversationId || null;
 65→
 66→      const userMsg: ChatMessage = {
 67→        id: generateId(),
 68→        role: 'user',
 69→        content: text,
 70→      };
 71→
 72→      const assistantId = generateId();
 73→      assistantIdRef.current = assistantId;
 74→      const assistantMsg: ChatMessage = {
 75→        id: assistantId,
 76→        role: 'assistant',
 77→        content: '',
 78→        toolCalls: [],
 79→        isStreaming: true,
 80→      };
 81→
 82→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 83→      setIsStreaming(true);
 84→      textBufferRef.current = '';
 85→      segmentsRef.current = [];
 86→      currentTextRef.current = '';
 87→      phaseRef.current = 'thinking';
 88→
 89→      // Build conversation history from current messages for resume fallback.
 90→      // Read from messagesRef (not the stale closure `messages`) so that
 91→      // switching conversations is reflected immediately.
 92→      const history = messagesRef.current
 93→        .filter((m) => m.role === 'user' || m.role === 'assistant')
 94→        .map((m) => ({ role: m.role, content: m.content }));
 95→
 96→      // If there's pending history from a delete, start a new Langfuse session with that context
 97→      const pendingHistory = pendingHistoryRef.current;
 98→      pendingHistoryRef.current = null;
 99→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
100→
101→      const controller = new AbortController();
102→      abortRef.current = controller;
103→
104→      // Extract all /skill-name references from message
105→      let actualMessage = text;
106→      let skills: string[] | undefined;
107→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
108→      if (slashMatches.length > 0) {
109→        skills = slashMatches.map((m) => m[1]);
110→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
111→      }
112→
113→      await runAgentLoop(
114→        actualMessage,
115→        sessionIdRef.current,
116→        langfuseSessionId,
117→        pendingHistory ?? (history.length > 0 ? history : null),
118→        conversationId,
119→        {
120→          onTextChunk: (chunk) => {
121→            textBufferRef.current += chunk;
122→            if (!flushTimerRef.current) {
123→              flushTimerRef.current = setTimeout(() => {
124→                flushText();
125→                flushTimerRef.current = null;
126→              }, 50);
127→            }
128→          },
129→          onThinkingDone: () => {
130→            // Extended thinking just ended and a text block is starting.
131→            // Create a thinking segment from accumulated thinking text.
132→            if (flushTimerRef.current) {
133→              clearTimeout(flushTimerRef.current);
134→              flushTimerRef.current = null;
135→            }
136→            flushText();
137→            if (currentTextRef.current.trim()) {
138→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
139→              currentTextRef.current = '';
140→            }
141→            phaseRef.current = 'answer';
142→            setMessages((prev) =>
143→              prev.map((m) =>
144→                m.id === assistantId
145→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
146→                  : m
147→              )
148→            );
149→          },
150→          onToolCall: (pending: ToolCallResult) => {
151→            if (flushTimerRef.current) {
152→              clearTimeout(flushTimerRef.current);
153→              flushTimerRef.current = null;
154→            }
155→            flushText();
156→            if (currentTextRef.current.trim()) {
157→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
158→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
159→              currentTextRef.current = '';
160→            }
161→            // Add a pending tool segment so the input is shown immediately
162→            segmentsRef.current.push({
163→              type: 'tool',
164→              toolResult: pending,
165→            });
166→            setMessages((prev) =>
167→              prev.map((m) =>
168→                m.id === assistantId
169→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
170→                  : m
171→              )
172→            );
173→          },
174→          onToolResult: (result: ToolCallResult) => {
175→            // Merge result into pending tool segment (keep input info, add output)
176→            const pendingIdx = segmentsRef.current.findIndex(
177→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
178→            );
179→            if (pendingIdx !== -1) {
