  1→import {
  2→  useCallback,
  3→  useEffect,
  4→  useRef,
  5→  useState,
  6→  type ReactNode,
  7→} from 'react';
  8→import { AgentContext } from '../hooks/useAgent';
  9→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
 10→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 11→import { useSessionId } from '../hooks/useSessionId';
 12→import { generateUUID } from '../utils/uuid';
 13→
 14→function generateId() {
 15→  return generateUUID();
 16→}
 17→
 18→export function AgentProvider({
 19→  children,
 20→  refreshTables,
 21→}: {
 22→  children: ReactNode;
 23→  refreshTables: () => Promise<void>;
 24→}) {
 25→  const userSessionId = useSessionId();
 26→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 27→  const [isStreaming, setIsStreaming] = useState(false);
 28→  const abortRef = useRef<AbortController | null>(null);
 29→  const textBufferRef = useRef('');
 30→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 31→  const assistantIdRef = useRef('');
 32→  const segmentsRef = useRef<ContentSegment[]>([]);
 33→  const currentTextRef = useRef('');
 34→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 35→  const sessionIdRef = useRef<string | null>(null);
 36→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 37→  // Keep a ref in sync with messages so sendMessage always reads the latest
 38→  const messagesRef = useRef<ChatMessage[]>(messages);
 39→  useEffect(() => { messagesRef.current = messages; }, [messages]);
 40→  // Cache messages per conversation so switching away doesn't lose in-progress data
 41→  const messagesCacheRef = useRef<Map<string, ChatMessage[]>>(new Map());
 42→  // Track which conversation is currently displayed so background streams can detect they're stale
 43→  const activeConversationIdRef = useRef<string | null>(null);
 44→  // Track which conversation owns the current SSE stream (set in sendMessage).
 45→  // Used as a fallback when React state is stale (e.g. user switches before re-render).
 46→  const streamConversationIdRef = useRef<string | null>(null);
 47→  // Generation counter: incremented on every stream-disrupting event (sendMessage,
 48→  // loadMessages, clearMessages).  Callbacks capture the generation at creation time
 49→  // and bail out if the ref has since advanced, preventing cross-conversation leaks.
 50→  const streamGenerationRef = useRef(0);
 51→
 52→  const flushText = useCallback(() => {
 53→    const text = textBufferRef.current;
 54→    if (!text) return;
 55→    const id = assistantIdRef.current;
 56→    currentTextRef.current += text;
 57→    setMessages((prev) =>
 58→      prev.map((m) =>
 59→        m.id === id ? { ...m, content: m.content + text } : m
 60→      )
 61→    );
 62→    textBufferRef.current = '';
 63→  }, []);
 64→
 65→  const sendMessage = useCallback(
 66→    async (text: string, conversationId?: string | null) => {
 67→      if (isStreaming) return;
 68→      streamConversationIdRef.current = conversationId || null;
 69→      const generation = ++streamGenerationRef.current;
 70→
 71→      const userMsg: ChatMessage = {
 72→        id: generateId(),
 73→        role: 'user',
 74→        content: text,
 75→      };
 76→
 77→      const assistantId = generateId();
 78→      assistantIdRef.current = assistantId;
 79→      const assistantMsg: ChatMessage = {
 80→        id: assistantId,
 81→        role: 'assistant',
 82→        content: '',
 83→        toolCalls: [],
 84→        isStreaming: true,
 85→      };
 86→
 87→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 88→      setIsStreaming(true);
 89→      textBufferRef.current = '';
 90→      segmentsRef.current = [];
 91→      currentTextRef.current = '';
 92→      phaseRef.current = 'thinking';
 93→
 94→      // Build conversation history from current messages for resume fallback.
 95→      // Read from messagesRef (not the stale closure `messages`) so that
 96→      // switching conversations is reflected immediately.
 97→      const history = messagesRef.current
 98→        .filter((m) => m.role === 'user' || m.role === 'assistant')
 99→        .map((m) => ({ role: m.role, content: m.content }));
100→
101→      // If there's pending history from a delete, start a new Langfuse session with that context
102→      const pendingHistory = pendingHistoryRef.current;
103→      pendingHistoryRef.current = null;
104→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
105→
106→      const controller = new AbortController();
107→      abortRef.current = controller;
108→
109→      // Extract all /skill-name references from message
110→      let actualMessage = text;
111→      let skills: string[] | undefined;
112→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
113→      if (slashMatches.length > 0) {
114→        skills = slashMatches.map((m) => m[1]);
115→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
116→      }
117→
118→      await runAgentLoop(
119→        actualMessage,
120→        sessionIdRef.current,
121→        langfuseSessionId,
122→        pendingHistory ?? (history.length > 0 ? history : null),
123→        conversationId,
124→        {
125→          onTextChunk: (chunk) => {
126→            if (streamGenerationRef.current !== generation) return;
127→            textBufferRef.current += chunk;
128→            if (!flushTimerRef.current) {
129→              flushTimerRef.current = setTimeout(() => {
130→                flushText();
131→                flushTimerRef.current = null;
132→              }, 50);
133→            }
134→          },
135→          onThinkingDone: () => {
136→            if (streamGenerationRef.current !== generation) return;
137→            // Extended thinking just ended and a text block is starting.
138→            // Create a thinking segment from accumulated thinking text.
139→            if (flushTimerRef.current) {
140→              clearTimeout(flushTimerRef.current);
141→              flushTimerRef.current = null;
142→            }
143→            flushText();
144→            if (currentTextRef.current.trim()) {
145→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
146→              currentTextRef.current = '';
147→            }
148→            phaseRef.current = 'answer';
149→            setMessages((prev) =>
150→              prev.map((m) =>
151→                m.id === assistantId
152→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
153→                  : m
154→              )
155→            );
156→          },
157→          onToolCall: (pending: ToolCallResult) => {
158→            if (streamGenerationRef.current !== generation) return;
159→            if (flushTimerRef.current) {
160→              clearTimeout(flushTimerRef.current);
161→              flushTimerRef.current = null;
162→            }
163→            flushText();
164→            if (currentTextRef.current.trim()) {
165→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
166→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
167→              currentTextRef.current = '';
168→            }
169→            // Add a pending tool segment so the input is shown immediately
170→            segmentsRef.current.push({
171→              type: 'tool',
172→              toolResult: pending,
173→            });
174→            setMessages((prev) =>
175→              prev.map((m) =>
176→                m.id === assistantId
177→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
178→                  : m
179→              )
180→            );
181→          },
182→          onToolResult: (result: ToolCallResult) => {
183→            if (streamGenerationRef.current !== generation) return;
184→            // Merge result into pending tool segment (keep input info, add output)
185→            const pendingIdx = segmentsRef.current.findIndex(
186→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
187→            );
188→            if (pendingIdx !== -1) {
189→              const pending = segmentsRef.current[pendingIdx].toolResult!;
190→              segmentsRef.current[pendingIdx] = {
191→                type: 'tool',
192→                toolResult: {
193→                  ...pending,
194→                  ...result,
195→                  sql: result.sql || pending.sql,
196→                  toolName: result.toolName || pending.toolName,
197→                  command: result.command || pending.command,
198→                  toolInput: result.toolInput || pending.toolInput,
199→                },
200→              };
201→            } else {
202→              segmentsRef.current.push({ type: 'tool', toolResult: result });
203→            }
204→            setMessages((prev) =>
205→              prev.map((m) =>
206→                m.id === assistantId
207→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
208→                  : m
209→              )
210→            );
211→            refreshTables();
212→            // When a skill is created, notify SkillsPanel to refresh
213→            if (result.toolName?.includes('create_skill')) {
214→              window.dispatchEvent(new CustomEvent('skills-updated'));
215→            }
216→            // When a memory is saved or forgotten, notify MemoriesPanel to refresh
217→            if (result.toolName?.includes('save_memory') || result.toolName?.includes('forget_memory')) {
218→              window.dispatchEvent(new CustomEvent('memories-updated'));
219→            }
220→          },
221→          onSubagentStart: (data) => {
222→            if (streamGenerationRef.current !== generation) return;
223→            if (flushTimerRef.current) {
224→              clearTimeout(flushTimerRef.current);
225→              flushTimerRef.current = null;
226→            }
227→            flushText();
228→            if (currentTextRef.current.trim()) {
229→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
230→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
231→              currentTextRef.current = '';
232→            }
233→            segmentsRef.current.push({
234→              type: 'subagent_start',
235→              subagentId: data.id,
236→              subagentName: data.name,
237→              text: data.prompt,
238→            });
239→            setMessages((prev) =>
240→              prev.map((m) =>
241→                m.id === assistantId
242→                  ? { ...m, segments: [...segmentsRef.current] }
243→                  : m
244→              )
245→            );
246→          },
247→          onSubagentEnd: (data) => {
248→            if (streamGenerationRef.current !== generation) return;
249→            segmentsRef.current.push({
250→              type: 'subagent_end',
