  1→import {
  2→  useCallback,
  3→  useEffect,
  4→  useRef,
  5→  useState,
  6→  type ReactNode,
  7→} from 'react';
  8→import { AgentContext } from '../hooks/useAgent';
  9→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
 10→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 11→import { useSessionId } from '../hooks/useSessionId';
 12→import { generateUUID } from '../utils/uuid';
 13→import { buildChatMessages } from '../utils/buildChatMessages';
 14→
 15→function generateId() {
 16→  return generateUUID();
 17→}
 18→
 19→export function AgentProvider({
 20→  children,
 21→  refreshTables,
 22→}: {
 23→  children: ReactNode;
 24→  refreshTables: () => Promise<void>;
 25→}) {
 26→  const userSessionId = useSessionId();
 27→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 28→  const [isStreaming, setIsStreaming] = useState(false);
 29→  const abortRef = useRef<AbortController | null>(null);
 30→  const textBufferRef = useRef('');
 31→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 32→  const assistantIdRef = useRef('');
 33→  const segmentsRef = useRef<ContentSegment[]>([]);
 34→  const currentTextRef = useRef('');
 35→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 36→  const sessionIdRef = useRef<string | null>(null);
 37→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 38→  // Keep a ref in sync with messages so sendMessage always reads the latest
 39→  const messagesRef = useRef<ChatMessage[]>(messages);
 40→  useEffect(() => { messagesRef.current = messages; }, [messages]);
 41→  // Cache messages per conversation so switching away doesn't lose in-progress data
 42→  const messagesCacheRef = useRef<Map<string, ChatMessage[]>>(new Map());
 43→  // Track which conversation is currently displayed so background streams can detect they're stale
 44→  const activeConversationIdRef = useRef<string | null>(null);
 45→  // Track which conversation owns the current SSE stream (set in sendMessage).
 46→  // Used as a fallback when React state is stale (e.g. user switches before re-render).
 47→  const streamConversationIdRef = useRef<string | null>(null);
 48→  // Generation counter: incremented on every stream-disrupting event (sendMessage,
 49→  // loadMessages, clearMessages).  Callbacks capture the generation at creation time
 50→  // and bail out if the ref has since advanced, preventing cross-conversation leaks.
 51→  const streamGenerationRef = useRef(0);
 52→
 53→  const flushText = useCallback(() => {
 54→    const text = textBufferRef.current;
 55→    if (!text) return;
 56→    const id = assistantIdRef.current;
 57→    currentTextRef.current += text;
 58→    setMessages((prev) =>
 59→      prev.map((m) =>
 60→        m.id === id ? { ...m, content: m.content + text } : m
 61→      )
 62→    );
 63→    textBufferRef.current = '';
 64→  }, []);
 65→
 66→  const sendMessage = useCallback(
 67→    async (text: string, conversationId?: string | null) => {
 68→      console.log('[CONV-DEBUG] sendMessage called', { text: text.slice(0, 30), conversationId, isStreaming, generation: streamGenerationRef.current });
 69→      if (isStreaming) { console.log('[CONV-DEBUG] sendMessage BLOCKED by isStreaming'); return; }
 70→      streamConversationIdRef.current = conversationId || null;
 71→      const generation = ++streamGenerationRef.current;
 72→      console.log('[CONV-DEBUG] sendMessage proceeding', { generation, conversationId });
 73→
 74→      const userMsg: ChatMessage = {
 75→        id: generateId(),
 76→        role: 'user',
 77→        content: text,
 78→      };
 79→
 80→      const assistantId = generateId();
 81→      assistantIdRef.current = assistantId;
 82→      const assistantMsg: ChatMessage = {
 83→        id: assistantId,
 84→        role: 'assistant',
 85→        content: '',
 86→        toolCalls: [],
 87→        isStreaming: true,
 88→      };
 89→
 90→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 91→      setIsStreaming(true);
 92→      textBufferRef.current = '';
 93→      segmentsRef.current = [];
 94→      currentTextRef.current = '';
 95→      phaseRef.current = 'thinking';
 96→
 97→      // Build conversation history from current messages for resume fallback.
 98→      // Read from messagesRef (not the stale closure `messages`) so that
 99→      // switching conversations is reflected immediately.
100→      const history = messagesRef.current
101→        .filter((m) => m.role === 'user' || m.role === 'assistant')
102→        .map((m) => ({ role: m.role, content: m.content }));
103→
104→      // If there's pending history from a delete, start a new Langfuse session with that context
105→      const pendingHistory = pendingHistoryRef.current;
106→      pendingHistoryRef.current = null;
107→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
108→
109→      const controller = new AbortController();
110→      abortRef.current = controller;
111→
112→      // Extract all /skill-name references from message
113→      let actualMessage = text;
114→      let skills: string[] | undefined;
115→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
116→      if (slashMatches.length > 0) {
117→        skills = slashMatches.map((m) => m[1]);
118→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
119→      }
120→
121→      await runAgentLoop(
122→        actualMessage,
123→        sessionIdRef.current,
124→        langfuseSessionId,
125→        pendingHistory ?? (history.length > 0 ? history : null),
126→        conversationId,
127→        {
128→          onTextChunk: (chunk) => {
129→            if (streamGenerationRef.current !== generation) return;
130→            textBufferRef.current += chunk;
131→            if (!flushTimerRef.current) {
132→              flushTimerRef.current = setTimeout(() => {
133→                flushText();
134→                flushTimerRef.current = null;
135→              }, 50);
